package net.zartra.gui;
import org.bukkit.event.inventory.ClickType;import org.junit.Test;import static org.junit.Assert.*;
public class ClickMapperTest {@Test public void mapsEveryPersistedClickType(){assertEquals(MenuClickType.LEFT,ClickMapper.resolve(false,true,false,ClickType.LEFT));assertEquals(MenuClickType.RIGHT,ClickMapper.resolve(false,false,true,ClickType.RIGHT));assertEquals(MenuClickType.SHIFT_LEFT,ClickMapper.resolve(true,true,false,ClickType.SHIFT_LEFT));assertEquals(MenuClickType.SHIFT_RIGHT,ClickMapper.resolve(true,false,true,ClickType.SHIFT_RIGHT));assertEquals(MenuClickType.MIDDLE,ClickMapper.resolve(false,false,false,ClickType.MIDDLE));assertEquals(MenuClickType.NUMBER_KEY,ClickMapper.resolve(false,false,false,ClickType.NUMBER_KEY));}@Test public void doubleClickIsExplicitlyBlocked(){assertTrue(ClickMapper.blocked(ClickType.DOUBLE_CLICK));assertFalse(ClickMapper.blocked(ClickType.LEFT));}}